const EDGE: f32 = 3.0;

fn update(scene: &mut GameScene<'_>, _time: &FrameTime) {
    if scene.counter_or("won", 0) == 1 {
        return;
    }
    let step = match (scene.pressed("left"), scene.pressed("right")) {
        (true, false) => -1.0,
        (false, true) => 1.0,
        _ => return,
    };
    let mut at = scene.object("Player").position();
    at[0] = (at[0] + step).clamp(-EDGE, EDGE);
    scene.object("Player").set_position(at);
    if at[0] == EDGE {
        scene.set_counter("won", 1);
        scene.set_hud("Message", |hud| hud.text = "You win!".into());
    }
}
